-- GenDB engine variant Q02-conjunct_permutation: template q02.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  s_acctbal,
  s_name,
  n_name,
  p_partkey,
  p_mfgr,
  s_address,
  s_phone,
  s_comment
FROM part, supplier, partsupp, nation, region
WHERE
  ps_supplycost = (
    SELECT
      MIN(ps_supplycost)
    FROM partsupp, supplier, nation, region
    WHERE
      r_name = $3
      AND n_regionkey = r_regionkey
      AND s_nationkey = n_nationkey
      AND s_suppkey = ps_suppkey
      AND p_partkey = ps_partkey
  )
  AND r_name = $3
  AND n_regionkey = r_regionkey
  AND s_nationkey = n_nationkey
  AND p_type LIKE $2
  AND p_size = $1
  AND s_suppkey = ps_suppkey
  AND p_partkey = ps_partkey
ORDER BY
  s_acctbal DESC,
  n_name,
  s_name,
  p_partkey
LIMIT 100
